import assert from "node:assert/strict";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(new URL("../../../../frontend/package.json", import.meta.url));
const { build } = require("esbuild");
const source = new URL("../../../../frontend/src/features/project-canvas/documents/task-summary.ts", import.meta.url);
const result = await build({ entryPoints: [fileURLToPath(source)], bundle: true, write: false, format: "esm", platform: "node", target: "es2022", logLevel: "silent" });
const { taskBlockSummary } = await import(`data:text/javascript;base64,${Buffer.from(result.outputFiles[0].text).toString("base64")}`);
const person = { kind: "user", id: "person", name: "Member" };
const assistant = { kind: "agent", id: "assistant", name: "Assistant" };
const task = { id: "task", title: "Review", status: "todo", revision: 3, assignee: person, executedBy: person, execution: { agent: assistant } };
const human = JSON.parse(JSON.stringify(taskBlockSummary(task)));
assert.deepEqual(human, { id: "task", title: "Review", status: "todo", revision: 3, assigneeUserId: "person", assigneeName: "Member", agentId: null });
const executing = { kind: "agent", id: "executing", name: "Researcher" };
const agent = taskBlockSummary({ ...task, executedBy: executing });
assert.equal(agent.agentId, executing.id);
assert.equal(agent.agentName, executing.name);
assert.equal(taskBlockSummary({ ...task, execution: {} }).agentId, null);
assert.equal(task.executedBy, person, "projection does not mutate the source");
console.log("Task summary: human work excludes assisting Agent, Agent work retains executor, optional fields and input immutability passed");
